+/** Picks a supported language from an Accept-Language header, or `fallback`. */
+export function chooseLanguage(header, fallback = "en") {
+  if (typeof header !== "string" || !header.trim()) return fallback;
+  let bestLang = null;
+  let bestQ = 0;
+  for (const part of header.split(",")) {
+    const [rawTag, ...params] = part.split(";").map((s) => s.trim());
+    if (!rawTag) continue;
+    const base = rawTag.split("-")[0].toLowerCase();
+    let q = 1;
+    let validQ = true;
+    for (const param of params) {
+      const eq = param.indexOf("=");
+      if (eq === -1) continue;
+      const key = param.slice(0, eq).trim().toLowerCase();
+      const val = param.slice(eq + 1).trim();
+      if (key === "q") {
+        if (!/^(?:0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/.test(val)) {
+          validQ = false;
+          break;
+        }
+        q = Number(val);
+      }
+    }
+    if (!validQ || q <= 0 || !LANGUAGES.includes(base)) continue;
+    if (q > bestQ) {
+      bestQ = q;
+      bestLang = base;
+    }
+  }
+  return bestLang ?? fallback;
+}
